create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','engineer','planner','maintenance','viewer');
create type public.asset_status as enum ('active','inactive','retired');
create type public.note_type as enum ('engineering','site_visit','maintenance','general','rCA');
create type public.document_type as enum ('manual','drawing','print','procedure','spreadsheet','photo','report','other');
create type public.failure_status as enum ('open','investigating','contained','closed');
create type public.project_status as enum ('planned','active','on_hold','completed','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, job_title text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.roles (id bigint generated by default as identity primary key, name public.app_role unique not null, description text, created_at timestamptz not null default now());
create table public.user_roles (user_id uuid not null references auth.users(id) on delete cascade, role_id bigint not null references public.roles(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,role_id));
create table public.sites (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, description text, timezone text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_memberships (user_id uuid not null references auth.users(id) on delete cascade, site_id uuid not null references public.sites(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,site_id));
create table public.areas (id uuid primary key default gen_random_uuid(), site_id uuid not null references public.sites(id) on delete cascade, code text not null, name text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(site_id,code));
create table public.production_lines (id uuid primary key default gen_random_uuid(), area_id uuid not null references public.areas(id) on delete cascade, code text not null, name text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(area_id,code));
create table public.assets (id uuid primary key default gen_random_uuid(), production_line_id uuid references public.production_lines(id) on delete set null, parent_asset_id uuid references public.assets(id) on delete set null, asset_tag text not null unique, name text not null, asset_class text, manufacturer text, model text, serial_number text, status public.asset_status not null default 'active', criticality smallint check(criticality between 1 and 5), description text, maximo_asset_id text, maximo_site_id text, maximo_location_id text, installed_at date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.asset_components (id uuid primary key default gen_random_uuid(), asset_id uuid not null references public.assets(id) on delete cascade, component_type text not null, name text not null, manufacturer text, model text, part_number text, serial_number text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
